    """The newest version in the list."""
    if not versions:
        raise ValueError("Empty versions list")

    # In ["v1.2.3", "1.2.4-rc1", "1.2.3"], 1.2.4-rc1 is newer than 1.2.3! My test assertion in test_latest was wrong (expected 1.2.3 instead of 1.2.4-rc1).
